Native protocol: return the declared GMPL envelope. result.answer is JSON matching the research proposal schema below. Every research evidence id must also occur in result.claims citations with its visible digest. Preserve supported findings and their provenance. Research data are in context.domain; the synthesis and constraint blocks render that complete context. Provide a stance. 
Proposal schema: {
  "$defs": {
    "NoveltyAdvisory": {
      "additionalProperties": false,
      "properties": {
        "rating": {
          "maximum": 1,
          "minimum": 0,
          "type": "number"
        },
        "reason": {
          "maxLength": 4096,
          "minLength": 1,
          "pattern": "\\S",
          "type": "string"
        }
      },
      "required": [
        "rating",
        "reason"
      ],
      "type": "object"
    },
    "ResearchHypothesisProposal": {
      "additionalProperties": false,
      "properties": {
        "baselineIds": {
          "items": {
            "$ref": "#/$defs/ResearchId"
          },
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "confounds": {
          "items": {
            "minLength": 1,
            "type": "string"
          },
          "type": "array"
        },
        "disconfirmingObservation": {
          "minLength": 1,
          "type": "string"
        },
        "evidenceIds": {
          "items": {
            "$ref": "#/$defs/ResearchId"
          },
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "nullHypothesis": {
          "minLength": 1,
          "type": "string"
        },
        "predictedObservation": {
          "minLength": 1,
          "type": "string"
        },
        "queries": {
          "items": {
            "maxLength": 4096,
            "minLength": 1,
            "pattern": "\\S",
            "type": "string"
          },
          "maxItems": 3,
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "statement": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "statement",
        "nullHypothesis",
        "predictedObservation",
        "disconfirmingObservation",
        "evidenceIds",
        "baselineIds",
        "confounds",
        "queries"
      ],
      "type": "object"
    },
    "ResearchId": {
      "pattern": "^[a-z][a-z0-9-]*$",
      "type": "string"
    }
  },
  "$id": "https://tangleai.dev/schemas/research-records/HypothesisSetProposal",
  "additionalProperties": false,
  "properties": {
    "advisory": {
      "$ref": "#/$defs/NoveltyAdvisory"
    },
    "hypotheses": {
      "items": {
        "$ref": "#/$defs/ResearchHypothesisProposal"
      },
      "maxItems": 8,
      "minItems": 1,
      "type": "array"
    }
  },
  "required": [
    "hypotheses",
    "advisory"
  ],
  "type": "object"
}

